-- Paridad TERCEROS: TMP del SSIS (VIGIA.TMP_TERCEROS) vs carga Python (VIGIA.TMP_TERCEROS_PY).
-- Crear TMP_TERCEROS_PY con la misma estructura y apuntar 'destino' del config.yaml a ella durante la prueba.
-- Resultado esperado: las dos primeras consultas sin filas y conteos iguales.
SELECT TIPIDE_CODIGO, NUMIDE, NOMBRES, APELLIDOS, SISGEO_CODIGO, TIPO, PROFESION_CODIGO, ACTIVIDAD_CODIGO, ACTIVO, PASIVO, PATRIMONIO, INGRESOS, EGRESOS, CUPOTOTAL, TIPCAL_CODIGO, TIPVIN_CODIGO, DIRECCION, TELEFONO, EMAIL, FECHAVINCULACION, FECHAACTUALIZACION, FUNCIONARIO_RESPONSABLE, CIIU_CODIGO, PEP, TIPPEP_CODIGO, SEGMENTO_CODIGO, SUCURSAL_CODIGO, FECHA_NACIMIENTO, EXENTOANALISIS, SEXO, ESTADO, AUTORIZANOTIFICACION, NATURALEZAJURIDICA, SISGEO_NACIONALIDAD, PAIS_NACIMIENTO, ESTADOCIVIL_CODIGO, NOMBREEMPRESALABORA, DIRECCIONEMPRESALABORA, LUGAREXPEDICION_CODIGO FROM VIGIA.TMP_TERCEROS
EXCEPT
SELECT TIPIDE_CODIGO, NUMIDE, NOMBRES, APELLIDOS, SISGEO_CODIGO, TIPO, PROFESION_CODIGO, ACTIVIDAD_CODIGO, ACTIVO, PASIVO, PATRIMONIO, INGRESOS, EGRESOS, CUPOTOTAL, TIPCAL_CODIGO, TIPVIN_CODIGO, DIRECCION, TELEFONO, EMAIL, FECHAVINCULACION, FECHAACTUALIZACION, FUNCIONARIO_RESPONSABLE, CIIU_CODIGO, PEP, TIPPEP_CODIGO, SEGMENTO_CODIGO, SUCURSAL_CODIGO, FECHA_NACIMIENTO, EXENTOANALISIS, SEXO, ESTADO, AUTORIZANOTIFICACION, NATURALEZAJURIDICA, SISGEO_NACIONALIDAD, PAIS_NACIMIENTO, ESTADOCIVIL_CODIGO, NOMBREEMPRESALABORA, DIRECCIONEMPRESALABORA, LUGAREXPEDICION_CODIGO FROM VIGIA.TMP_TERCEROS_PY;

SELECT TIPIDE_CODIGO, NUMIDE, NOMBRES, APELLIDOS, SISGEO_CODIGO, TIPO, PROFESION_CODIGO, ACTIVIDAD_CODIGO, ACTIVO, PASIVO, PATRIMONIO, INGRESOS, EGRESOS, CUPOTOTAL, TIPCAL_CODIGO, TIPVIN_CODIGO, DIRECCION, TELEFONO, EMAIL, FECHAVINCULACION, FECHAACTUALIZACION, FUNCIONARIO_RESPONSABLE, CIIU_CODIGO, PEP, TIPPEP_CODIGO, SEGMENTO_CODIGO, SUCURSAL_CODIGO, FECHA_NACIMIENTO, EXENTOANALISIS, SEXO, ESTADO, AUTORIZANOTIFICACION, NATURALEZAJURIDICA, SISGEO_NACIONALIDAD, PAIS_NACIMIENTO, ESTADOCIVIL_CODIGO, NOMBREEMPRESALABORA, DIRECCIONEMPRESALABORA, LUGAREXPEDICION_CODIGO FROM VIGIA.TMP_TERCEROS_PY
EXCEPT
SELECT TIPIDE_CODIGO, NUMIDE, NOMBRES, APELLIDOS, SISGEO_CODIGO, TIPO, PROFESION_CODIGO, ACTIVIDAD_CODIGO, ACTIVO, PASIVO, PATRIMONIO, INGRESOS, EGRESOS, CUPOTOTAL, TIPCAL_CODIGO, TIPVIN_CODIGO, DIRECCION, TELEFONO, EMAIL, FECHAVINCULACION, FECHAACTUALIZACION, FUNCIONARIO_RESPONSABLE, CIIU_CODIGO, PEP, TIPPEP_CODIGO, SEGMENTO_CODIGO, SUCURSAL_CODIGO, FECHA_NACIMIENTO, EXENTOANALISIS, SEXO, ESTADO, AUTORIZANOTIFICACION, NATURALEZAJURIDICA, SISGEO_NACIONALIDAD, PAIS_NACIMIENTO, ESTADOCIVIL_CODIGO, NOMBREEMPRESALABORA, DIRECCIONEMPRESALABORA, LUGAREXPEDICION_CODIGO FROM VIGIA.TMP_TERCEROS;

SELECT (SELECT COUNT(*) FROM VIGIA.TMP_TERCEROS) AS SSIS, (SELECT COUNT(*) FROM VIGIA.TMP_TERCEROS_PY) AS PYTHON;
